import sys

def find_minimum(root, min_so_far=None):
    if not root:
        return None

    if not min_so_far:
        min_so_far = root.val

    while (root.left and min_so_far != root.val):
        root = root.left
        min_so_far = min(min_so_far, root.val)

def insert(root, value):
    root.val = value  # Insert the smallest integer into the BST
    if not root:
        root = Node(value)
    else:
        root.left = insert(root.left, value)
        if value < root:
            root = root.left
        else:
            root.right = insert(root.right, value)

def main():
    n = int(input())
    root = Node()
    for num in input().split():
        root = insert(root, int(num))
    value = find_minimum(root)  # Find node having minimum value in BST
    print(value)


class Node:
    def __init__(self, value):
    self.val = value
    self.left = None
    self.right = None

if __name__ == '__main__':
main()
